// SPDX-License-Identifier: MIT
import './abstract/Delegatable.sol';
import './lib/ChainUtils.sol';
import './lib/TradingLib.sol';
import './interfaces/IOstiumTrading.sol';
import './interfaces/IOstiumRegistry.sol';
import './interfaces/IOstiumPairInfos.sol';
import './interfaces/IOstiumTradingCallbacks.sol';
import './interfaces/IOstiumTradingStorage.sol';
import './interfaces/IOstiumPriceRouter.sol';
import '@openzeppelin/contracts/utils/math/Math.sol';
import '@openzeppelin/contracts/utils/math/SafeCast.sol';
import '@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol';

pragma solidity ^0.8.24;

contract OstiumTrading is IOstiumTrading, Delegatable, Initializable {
    using SafeCast for uint256;
    using Math for uint256;

    // Contracts (constant)
    IOstiumRegistry public registry;

    // Params (constant)
    uint64 constant PRECISION_18 = 1e18;
    uint32 constant PRECISION_6 = 1e6;
    uint16 constant MAX_GAIN_P = 900;
    uint16 constant PERCENT_BASE = 100e2; // 100% in precision 2 and also the MAX_SLIPPAGE_P
    uint32 constant MAX_BUILDER_FEE_PERCENT = 500000; // 0.5% // PRECISION_6

    // Params (adjustable)
    uint256 public maxAllowedCollateral; // PRECISION_6
    uint16 public marketOrdersTimeout; // block (eg. 30)
    uint16 public triggerTimeout; // block (eg. 30)

    // State
    bool public isPaused; // Prevent opening new trades
    bool public isDone; // Prevent any interaction with the contract

    constructor() {
        _disableInitializers();
    }

    function initialize(
        IOstiumRegistry _registry,
        uint256 _maxAllowedCollateral,
        uint16 _marketOrdersTimeout,
        uint16 _triggerTimeout
    ) external initializer {
        if (address(_registry) == address(0)) {
            revert WrongParams();
        }

        registry = _registry;
        _setTriggerTimeout(_triggerTimeout);
        _setMaxAllowedCollateral(_maxAllowedCollateral);
        _setMarketOrdersTimeout(_marketOrdersTimeout);
    }

    // Modifiers
    modifier onlyGov() {
        isGov();
        _;
    }

    modifier onlyManager() {
        isManager();
        _;
    }

    modifier notDone() {
        isNotDone();
        _;
    }

    modifier onlyTradesUpKeep() {
        _onlyTradesUpKeep();
        _;
    }

    modifier notPaused() {
        isNotPaused();
        _;
    }

    modifier pairIndexListed(uint16 pairIndex) {
        isPairIndexListed(pairIndex);
        _;
    }

    function isPairIndexListed(uint16 pairIndex) private view {
        if (!IOstiumPairsStorage(registry.getContractAddress('pairsStorage')).isPairIndexListed(pairIndex)) {
            revert PairNotListed(pairIndex);
        }
    }

    function isNotPaused() private view {
        if (isPaused) revert IsPaused();
    }

    function isGov() private view {
        if (msg.sender != registry.gov()) {
            revert NotGov(msg.sender);
        }
    }

    function isManager() private view {
        if (msg.sender != registry.manager()) {
            revert NotManager(msg.sender);
        }
    }

    function isNotDone() private view {
        if (isDone) {
            revert IsDone();
        }
    }

    function _onlyTradesUpKeep() private view {
        if (msg.sender != address(registry.getContractAddress(bytes32('tradesUpKeep')))) {
            revert NotTradesUpKeep(msg.sender);
        }
    }

    function setMaxAllowedCollateral(uint256 value) external onlyGov {
        _setMaxAllowedCollateral(value);
    }

    function _setMaxAllowedCollateral(uint256 value) private {
        if (value == 0) {
            revert WrongParams();
        }
        maxAllowedCollateral = value;

        emit MaxAllowedCollateralUpdated(value);
    }

    function setMarketOrdersTimeout(uint256 value) external onlyGov {
        _setMarketOrdersTimeout(value);
    }

    function _setMarketOrdersTimeout(uint256 value) private {
        if (value == 0 || value > type(uint16).max) {
            revert WrongParams();
        }
        marketOrdersTimeout = value.toUint16();

        emit MarketOrdersTimeoutUpdated(marketOrdersTimeout);
    }

    function setTriggerTimeout(uint256 value) external onlyGov {
        _setTriggerTimeout(value);
    }

    function _setTriggerTimeout(uint256 value) private {
        if (value == 0 || value > type(uint16).max) {
            revert WrongParams();
        }
        triggerTimeout = value.toUint16();
        emit TriggerTimeoutUpdated(triggerTimeout);
    }

    function pause() external onlyManager {
        isPaused = !isPaused;

        emit Paused(isPaused);
    }

    function done() external onlyGov {
        isDone = !isDone;

        emit Done(isDone);
    }

    function openTrade(
        IOstiumTradingStorage.Trade calldata t,
        IOstiumTradingStorage.BuilderFee calldata bf,
        IOstiumTradingStorage.OpenOrderType orderType,
        uint256 slippageP // for market orders only
    ) external notDone notPaused pairIndexListed(t.pairIndex) {
        address sender = _msgSender();
        if (t.openPrice == 0) {
            revert WrongParams();
        }

        if (orderType == IOstiumTradingStorage.OpenOrderType.MARKET) {
            if (slippageP == 0 || slippageP >= PERCENT_BASE) {
                revert WrongParams();
            }
        } else {
            if (slippageP != 0) {
                revert WrongParams();
            }
        }

        if (bf.builder != address(0) && bf.builderFee > MAX_BUILDER_FEE_PERCENT) {
            revert WrongParams();
        }

        IOstiumPairsStorage pairsStored = IOstiumPairsStorage(registry.getContractAddress('pairsStorage'));
        IOstiumTradingStorage storageT = IOstiumTradingStorage(registry.getContractAddress('tradingStorage'));
        IOstiumPairInfos pairInfos = IOstiumPairInfos(registry.getContractAddress('pairInfos'));

        (, uint32 takerFeeP,,,,) = pairInfos.pairOpeningFees(t.pairIndex);
        TradingLib.getOpenTradeRevert(storageT, pairsStored, sender, t, maxAllowedCollateral, takerFeeP, bf);

        storageT.transferUsdc(sender, address(storageT), t.collateral);

        if (orderType != IOstiumTradingStorage.OpenOrderType.MARKET) {
            uint8 index = storageT.firstEmptyOpenLimitIndex(sender, t.pairIndex);
            uint32 currTimestamp = block.timestamp.toUint32();

            storageT.storeOpenLimitOrder(
                IOstiumTradingStorage.OpenLimitOrder(
                    t.collateral,
                    t.openPrice,
                    t.tp,
                    t.sl,
                    sender,
                    t.leverage,
                    currTimestamp,
                    currTimestamp,
                    t.pairIndex,
                    orderType,
                    index,
                    t.buy
                ),
                bf
            );

            emit OpenLimitPlacedV2(sender, t.pairIndex, index, t, orderType, bf);
        } else {
            uint256 orderId = IOstiumPriceRouter(registry.getContractAddress('priceRouter'))
                .getPrice(t.pairIndex, IOstiumPriceUpKeep.OrderType.MARKET_OPEN, block.timestamp);

            storageT.storePendingMarketOrder(
                IOstiumTradingStorage.PendingMarketOrderV2(
                    0,
                    t.openPrice,
                    slippageP.toUint32(),
                    IOstiumTradingStorage.Trade(t.collateral, 0, t.tp, t.sl, sender, t.leverage, t.pairIndex, 0, t.buy),
                    0
                ),
                orderId,
                true,
                bf
            );

            emit MarketOpenOrderInitiated(orderId, sender, t.pairIndex);
        }
    }

    function closeTradeMarket(
        uint16 pairIndex,
        uint8 index,
        uint16 closePercentage,
        uint192 marketPrice,
        uint32 slippageP
    ) external notDone {
        IOstiumTradingStorage storageT = IOstiumTradingStorage(registry.getContractAddress('tradingStorage'));
        IOstiumPairsStorage pairsStorage = IOstiumPairsStorage(registry.getContractAddress('pairsStorage'));

        address sender = _msgSender();

        if (closePercentage > PERCENT_BASE) {
            revert WrongParams();
        }

        if (marketPrice == 0 || slippageP == 0 || slippageP > PERCENT_BASE) {
            revert WrongParams();
        }

        if (closePercentage == 0) {
            closePercentage = PERCENT_BASE;
        }

        IOstiumTradingStorage.Trade memory t = storageT.getOpenTrade(sender, pairIndex, index);
        IOstiumTradingStorage.TradeInfo memory i = storageT.getOpenTradeInfo(sender, pairIndex, index);

        TradingLib.getCloseTradeRevert(storageT, pairsStorage, sender, t, triggerTimeout, closePercentage);

        uint256 orderId = IOstiumPriceRouter(registry.getContractAddress('priceRouter'))
            .getPrice(pairIndex, IOstiumPriceUpKeep.OrderType.MARKET_CLOSE, block.timestamp);

        // Always charge oracle fee for both partial and full closes to prevent griefing
        uint256 oracleFee = pairsStorage.pairOracleFee(pairIndex);
        storageT.transferUsdc(sender, address(storageT), oracleFee);
        storageT.handleOracleFee(oracleFee);
        emit OracleFeeCharged(orderId, sender, pairIndex, oracleFee);

        storageT.storePendingMarketOrder(
            IOstiumTradingStorage.PendingMarketOrderV2(
                0,
                marketPrice,
                slippageP,
                IOstiumTradingStorage.Trade(0, 0, 0, 0, sender, 0, pairIndex, index, t.buy),
                closePercentage
            ),
            orderId,
            false,
            IOstiumTradingStorage.BuilderFee(address(0), 0)
        );

        storageT.setTrigger(sender, pairIndex, index, IOstiumTradingStorage.LimitOrder.PENDING_CLOSE);
        storageT.storePendingMarketCloseTradeId(orderId, i.tradeId);

        emit MarketCloseOrderInitiatedV2(orderId, i.tradeId, sender, pairIndex, closePercentage);
    }

    function updateOpenLimitOrder(uint16 pairIndex, uint8 index, uint192 price, uint192 tp, uint192 sl)
        external
        notDone
    {
        if (price == 0) {
            revert WrongParams();
        }

        address sender = _msgSender();
        IOstiumTradingStorage storageT = IOstiumTradingStorage(registry.getContractAddress('tradingStorage'));

        if (!storageT.hasOpenLimitOrder(sender, pairIndex, index)) {
            revert NoLimitFound(sender, pairIndex, index);
        }

        IOstiumTradingStorage.OpenLimitOrder memory o = storageT.getOpenLimitOrder(sender, pairIndex, index);

        o.targetPrice = price;
        o.tp = tp;
        o.sl = sl;

        TradingLib.getUpdateOpenLimitOrderRevert(storageT, sender, o, pairIndex, index, triggerTimeout);

        storageT.updateOpenLimitOrder(o);

        emit OpenLimitUpdated(sender, pairIndex, index, price, tp, sl);
    }

    function cancelOpenLimitOrder(uint16 pairIndex, uint8 index) external notDone {
        address sender = _msgSender();
        IOstiumTradingStorage storageT = IOstiumTradingStorage(registry.getContractAddress('tradingStorage'));

        TradingLib.getCancelOpenLimitOrderRevert(storageT, sender, pairIndex, index, triggerTimeout);

        IOstiumTradingStorage.OpenLimitOrder memory o = storageT.getOpenLimitOrder(sender, pairIndex, index);

        storageT.unregisterOpenLimitOrder(sender, pairIndex, index);

        uint256 oracleFee = IOstiumPairsStorage(registry.getContractAddress('pairsStorage')).pairOracleFee(pairIndex);
        if (o.collateral > oracleFee) {
            storageT.transferUsdc(address(storageT), sender, o.collateral - oracleFee);
        } else {
            oracleFee = o.collateral;
        }
        storageT.handleOracleFee(oracleFee);

        emit OracleFeeChargedLimitCancelled(sender, pairIndex, oracleFee);
        emit OpenLimitCanceled(sender, pairIndex, index);
    }

    function updateTp(uint16 pairIndex, uint8 index, uint192 newTp) external notDone {
        address sender = _msgSender();
        IOstiumTradingStorage storageT = IOstiumTradingStorage(registry.getContractAddress('tradingStorage'));

        if (!TradingLib.checkNoPendingTrigger(
                storageT, sender, pairIndex, index, IOstiumTradingStorage.LimitOrder.TP, triggerTimeout
            )) {
            revert TriggerPending(sender, pairIndex, index);
        }

        if (!TradingLib.checkNoPendingTrigger(
                storageT, sender, pairIndex, index, IOstiumTradingStorage.LimitOrder.PENDING_CLOSE, triggerTimeout
            )) {
            revert TriggerPending(sender, pairIndex, index);
        }

        IOstiumTradingStorage.Trade memory t = storageT.getOpenTrade(sender, pairIndex, index);

        if (t.leverage == 0) {
            revert NoTradeFound(sender, pairIndex, index);
        }

        (,, uint32 initialLeverage,,,,) = storageT.openTradesInfo(sender, pairIndex, index);
        uint256 maxTpDist = t.openPrice * MAX_GAIN_P / (initialLeverage > t.leverage ? initialLeverage : t.leverage);

        if (
            newTp != 0
                && (t.buy
                        ? newTp > t.openPrice + maxTpDist
                        : newTp < (maxTpDist < t.openPrice ? t.openPrice - maxTpDist : 0))
        ) revert WrongTP();

        storageT.updateTp(sender, pairIndex, index, newTp);

        emit TpUpdated(storageT.getOpenTradeInfo(sender, pairIndex, index).tradeId, sender, pairIndex, index, newTp);
    }

    function updateSl(uint16 pairIndex, uint8 index, uint192 newSl) external notDone {
        IOstiumTradingStorage storageT = IOstiumTradingStorage(registry.getContractAddress('tradingStorage'));

        address sender = _msgSender();
        if (!TradingLib.checkNoPendingTrigger(
                storageT, sender, pairIndex, index, IOstiumTradingStorage.LimitOrder.SL, triggerTimeout
            )) {
            revert TriggerPending(sender, pairIndex, index);
        }

        if (!TradingLib.checkNoPendingTrigger(
                storageT, sender, pairIndex, index, IOstiumTradingStorage.LimitOrder.PENDING_CLOSE, triggerTimeout
            )) {
            revert TriggerPending(sender, pairIndex, index);
        }

        IOstiumTradingStorage.Trade memory t = storageT.getOpenTrade(sender, pairIndex, index);

        if (t.leverage == 0) {
            revert NoTradeFound(sender, pairIndex, index);
        }

        uint8 maxSL_P = IOstiumTradingCallbacks(registry.getContractAddress('callbacks')).maxSl_P();
        uint256 maxSlDist = t.openPrice * maxSL_P / t.leverage;

        if (newSl != 0 && (t.buy ? newSl < t.openPrice - maxSlDist : newSl > t.openPrice + maxSlDist)) {
            revert WrongSL();
        }

        storageT.updateSl(sender, pairIndex, index, newSl);

        emit SlUpdated(storageT.getOpenTradeInfo(sender, pairIndex, index).tradeId, sender, pairIndex, index, newSl);
    }

    function topUpCollateral(uint16 pairIndex, uint8 index, uint256 topUpAmount) external notDone {
        address sender = _msgSender();
        IOstiumTradingStorage storageT = IOstiumTradingStorage(registry.getContractAddress('tradingStorage'));
        IOstiumPairsStorage pairsStorage = IOstiumPairsStorage(registry.getContractAddress('pairsStorage'));

        IOstiumTradingStorage.Trade memory t = storageT.getOpenTrade(sender, pairIndex, index);

        if (t.leverage == 0) {
            revert NoTradeFound(sender, pairIndex, index);
        }
        if (topUpAmount == 0) {
            revert WrongParams();
        }
        if (!TradingLib.checkNoPendingTriggers(storageT, t.trader, t.pairIndex, t.index, triggerTimeout)) {
            revert TriggerPending(t.trader, t.pairIndex, t.index);
        }
        uint256 tradeSize = t.collateral.mulDiv(t.leverage, 100, Math.Rounding.Ceil);
        uint256 newCollateral = t.collateral + topUpAmount;
        uint32 newLeverage = (tradeSize * PRECISION_6 / newCollateral / 1e4).toUint32();

        if (tradeSize * PRECISION_6 % (newCollateral * 1e4) != 0) {
            newLeverage += 1;
            newCollateral = tradeSize * 1e2 / newLeverage;

            if (newCollateral > t.collateral) {
                topUpAmount = newCollateral - t.collateral;
            } else {
                revert WrongParams();
            }
        }
        if (pairsStorage.groupCollateral(pairIndex, t.buy) + topUpAmount > pairsStorage.groupMaxCollateral(pairIndex)) {
            revert ExposureLimits();
        }
        if (newCollateral > maxAllowedCollateral) {
            revert AboveMaxAllowedCollateral();
        }
        if (newLeverage >= t.leverage || newLeverage < pairsStorage.pairMinLeverage(t.pairIndex)) {
            revert WrongLeverage(newLeverage);
        }

        t.leverage = newLeverage;
        t.collateral = newCollateral;

        storageT.transferUsdc(sender, address(storageT), topUpAmount);

        storageT.updateTrade(t);
        pairsStorage.updateGroupCollateral(t.pairIndex, topUpAmount, t.buy, true);

        emit TopUpCollateralExecuted(
            storageT.getOpenTradeInfo(sender, pairIndex, index).tradeId, sender, pairIndex, topUpAmount, t.leverage
        );
    }

    function removeCollateral(uint16 pairIndex, uint8 index, uint256 removeAmount) external notDone notPaused {
        address sender = _msgSender();
        IOstiumTradingStorage storageT = IOstiumTradingStorage(registry.getContractAddress('tradingStorage'));
        IOstiumPairsStorage pairsStorage = IOstiumPairsStorage(registry.getContractAddress('pairsStorage'));

        IOstiumTradingStorage.Trade memory t = storageT.getOpenTrade(sender, pairIndex, index);

        if (t.leverage == 0) {
            revert NoTradeFound(sender, pairIndex, index);
        }
        if (removeAmount == 0 || removeAmount >= t.collateral) {
            revert WrongParams();
        }
        if (!TradingLib.checkNoPendingTriggers(storageT, t.trader, t.pairIndex, t.index, triggerTimeout)) {
            revert TriggerPending(t.trader, t.pairIndex, t.index);
        }
        uint256 tradeSize = t.collateral.mulDiv(t.leverage, 100, Math.Rounding.Ceil);
        uint256 newCollateral = t.collateral - removeAmount;
        uint32 newLeverage = (tradeSize * PRECISION_6 / newCollateral / 1e4).toUint32();

        if (tradeSize * PRECISION_6 % (newCollateral * 1e4) != 0) {
            newCollateral = tradeSize * 1e2 / newLeverage;

            if (newCollateral < t.collateral) {
                removeAmount = t.collateral - newCollateral;
            } else {
                revert WrongParams();
            }
        }

        if (newLeverage <= t.leverage || newLeverage > pairsStorage.pairMaxLeverage(t.pairIndex)) {
            revert WrongLeverage(newLeverage);
        }

        uint256 orderId = IOstiumPriceRouter(registry.getContractAddress('priceRouter'))
            .getPrice(pairIndex, IOstiumPriceUpKeep.OrderType.REMOVE_COLLATERAL, block.timestamp);

        uint256 tradeId = storageT.getOpenTradeInfo(sender, pairIndex, index).tradeId;

        storageT.storePendingRemoveCollateral(
            IOstiumTradingStorage.PendingRemoveCollateral(removeAmount, sender, pairIndex, index, tradeId), orderId
        );

        storageT.setTrigger(t.trader, pairIndex, index, IOstiumTradingStorage.LimitOrder.REMOVE_COLLATERAL);

        uint256 oracleFee = pairsStorage.pairOracleFee(pairIndex);
        storageT.transferUsdc(sender, address(storageT), oracleFee);
        storageT.handleOracleFee(oracleFee);

        emit RemoveCollateralInitiated(tradeId, orderId, sender, pairIndex, removeAmount);
    }

    function executeAutomationOrder(
        IOstiumTradingStorage.LimitOrder orderType,
        address trader,
        uint16 pairIndex,
        uint8 index,
        uint256 priceTimestamp
    ) external onlyTradesUpKeep notDone pairIndexListed(pairIndex) returns (IOstiumTrading.AutomationOrderStatus) {
        if (
            orderType == IOstiumTradingStorage.LimitOrder.REMOVE_COLLATERAL
                || orderType == IOstiumTradingStorage.LimitOrder.PENDING_CLOSE
        ) {
            revert WrongParams();
        }

        IOstiumTradingStorage storageT = IOstiumTradingStorage(registry.getContractAddress('tradingStorage'));

        IOstiumTradingStorage.Trade memory t;

        if (orderType == IOstiumTradingStorage.LimitOrder.OPEN) {
            if (!storageT.hasOpenLimitOrder(trader, pairIndex, index)) {
                return IOstiumTrading.AutomationOrderStatus.NO_LIMIT;
            }

            if (isPaused) {
                return IOstiumTrading.AutomationOrderStatus.PAUSED;
            }

            IOstiumTradingStorage.OpenLimitOrder memory openOrder = storageT.getOpenLimitOrder(trader, pairIndex, index);
            if (priceTimestamp < openOrder.lastUpdated) {
                return IOstiumTrading.AutomationOrderStatus.BACKDATED_EXECUTION;
            }
        } else {
            t = storageT.getOpenTrade(trader, pairIndex, index);
            IOstiumTradingStorage.TradeInfo memory tInfo = storageT.getOpenTradeInfo(trader, pairIndex, index);

            if (t.leverage == 0) return IOstiumTrading.AutomationOrderStatus.NO_TRADE;

            if (priceTimestamp < tInfo.createdAt) {
                return IOstiumTrading.AutomationOrderStatus.BACKDATED_EXECUTION;
            }

            if (
                orderType == IOstiumTradingStorage.LimitOrder.SL
                    && (t.sl == 0 || (t.sl != 0 && tInfo.slLastUpdated > priceTimestamp))
            ) {
                return IOstiumTrading.AutomationOrderStatus.NO_SL;
            }
            if (
                orderType == IOstiumTradingStorage.LimitOrder.TP
                    && (t.tp == 0 || (t.tp != 0 && tInfo.tpLastUpdated > priceTimestamp))
            ) {
                return IOstiumTrading.AutomationOrderStatus.NO_TP;
            }
        }

        if (!TradingLib.checkNoPendingTrigger(storageT, trader, pairIndex, index, orderType, triggerTimeout)) {
            return IOstiumTrading.AutomationOrderStatus.PENDING_TRIGGER;
        }

        uint256 orderId = IOstiumPriceRouter(registry.getContractAddress('priceRouter'))
            .getPrice(
                pairIndex,
                orderType == IOstiumTradingStorage.LimitOrder.OPEN
                    ? IOstiumPriceUpKeep.OrderType.LIMIT_OPEN
                    : IOstiumPriceUpKeep.OrderType.LIMIT_CLOSE,
                priceTimestamp
            );
        // For close orders (TP/SL/LIQ), store tradeId to validate the trade hasn't been replaced when callback executes
        // For OPEN orders (limit orders), store limitOrderId to validate the limit order hasn't been replaced
        uint256 idToStore = orderType == IOstiumTradingStorage.LimitOrder.OPEN
            ? storageT.limitOrderIds(trader, pairIndex, index)
            : storageT.getOpenTradeInfo(trader, pairIndex, index).tradeId;

        storageT.storePendingAutomationOrder(
            IOstiumTradingStorage.PendingAutomationOrder(trader, pairIndex, index, orderType, idToStore), orderId
        );
        storageT.setTrigger(trader, pairIndex, index, orderType);

        if (orderType == IOstiumTradingStorage.LimitOrder.OPEN) {
            emit AutomationOpenOrderInitiated(orderId, trader, pairIndex, index);
        } else {
            emit AutomationCloseOrderInitiated(orderId, idToStore, trader, pairIndex, orderType);
        }

        return IOstiumTrading.AutomationOrderStatus.SUCCESS;
    }

    function openTradeMarketTimeout(uint256 _order) external notDone {
        address sender = _msgSender();
        IOstiumTradingStorage storageT = IOstiumTradingStorage(registry.getContractAddress('tradingStorage'));

        (uint256 _block, uint192 wantedPrice, uint32 slippageP, IOstiumTradingStorage.Trade memory trade,) =
            storageT.reqID_pendingMarketOrder(_order);

        if (trade.trader == address(0)) {
            revert NoTradeToTimeoutFound(_order);
        }

        if (trade.trader != sender) {
            revert NotYourOrder(_order, trade.trader);
        }

        if (trade.leverage == 0) {
            revert NotOpenMarketTimeoutOrder(_order);
        }

        if (_block != 0 && ChainUtils.getBlockNumber() < _block + marketOrdersTimeout) {
            revert WaitTimeout(_order);
        }

        storageT.unregisterPendingMarketOrder(_order, true);
        storageT.transferUsdc(address(storageT), sender, trade.collateral);

        emit MarketOpenTimeoutExecutedV2(
            _order,
            IOstiumTradingStorage.PendingMarketOrderV2({
                block: _block, wantedPrice: wantedPrice, slippageP: slippageP, trade: trade, percentage: 0
            })
        );
    }

    function closeTradeMarketTimeout(uint256 _order, bool retry) external notDone {
        address sender = _msgSender();
        IOstiumTradingStorage storageT = IOstiumTradingStorage(registry.getContractAddress('tradingStorage'));

        (
            uint256 _block,
            uint192 wantedPrice,
            uint32 slippageP,
            IOstiumTradingStorage.Trade memory trade,
            uint16 percentage
        ) = storageT.reqID_pendingMarketOrder(_order);

        if (trade.trader == address(0)) {
            revert NoTradeToTimeoutFound(_order);
        }

        if (trade.trader != sender) {
            revert NotYourOrder(_order, trade.trader);
        }

        if (trade.leverage > 0) {
            revert NotCloseMarketTimeoutOrder(_order);
        }

        if (_block == 0 || ChainUtils.getBlockNumber() < _block + marketOrdersTimeout) {
            revert WaitTimeout(_order);
        }

        storageT.unregisterPendingMarketOrder(_order, false);
        storageT.clearDeprecatedBeingMarketClosed(sender, trade.pairIndex, trade.index);
        storageT.unregisterTrigger(sender, trade.pairIndex, trade.index, IOstiumTradingStorage.LimitOrder.PENDING_CLOSE);

        uint256 tradeId = storageT.getOpenTradeInfo(sender, trade.pairIndex, trade.index).tradeId;

        if (retry) {
            (bool success,) = address(this)
                .delegatecall(
                    abi.encodeWithSignature(
                        'closeTradeMarket(uint16,uint8,uint16,uint192,uint32)',
                        trade.pairIndex,
                        trade.index,
                        percentage,
                        wantedPrice,
                        slippageP
                    )
                );
            if (!success) {
                emit MarketCloseFailed(tradeId, sender, trade.pairIndex);
            }
        }
        // Always refund oracle fee regardless of partial or full close
        uint256 oracleFee =
            IOstiumPairsStorage(registry.getContractAddress('pairsStorage')).pairOracleFee(trade.pairIndex);
        storageT.refundOracleFee(oracleFee);
        storageT.transferUsdc(address(storageT), sender, oracleFee);
        emit OracleFeeRefunded(_order, sender, trade.pairIndex, oracleFee);

        emit MarketCloseTimeoutExecutedV2(
            _order,
            tradeId,
            IOstiumTradingStorage.PendingMarketOrderV2({
                trade: trade, block: _block, wantedPrice: wantedPrice, slippageP: slippageP, percentage: percentage
            })
        );
    }
}

src/OstiumTradingCallbacks.sol.content:
// SPDX-License-Identifier: MIT
import '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import '@openzeppelin/contracts/utils/math/Math.sol';
import '@openzeppelin/contracts/utils/math/SafeCast.sol';
import '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import '@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol';

import './interfaces/IOstiumTradingStorage.sol';
import './interfaces/IOstiumPairInfos.sol';
import './interfaces/IOstiumRegistry.sol';
import './interfaces/IOstiumTradingCallbacks.sol';
import './interfaces/IOstiumPairsStorage.sol';

import './interfaces/IOstiumOpenPnl.sol';
import './lib/TradingCallbacksLib.sol';

pragma solidity ^0.8.24;

contract OstiumTradingCallbacks is IOstiumTradingCallbacks, Initializable {
    using Math for uint256;
    using SafeCast for uint256;
    using SafeCast for uint192;

    // Contracts (constant)
    IOstiumRegistry public registry;

    // Params (constant)
    uint64 constant PRECISION_18 = 1e18;
    uint32 constant PRECISION_6 = 1e6;

    // State
    uint8 public maxSl_P; // How much % from the open price the stop loss can be set
    bool public isPaused; // Prevent opening new trades
    bool public isDone; // Prevent any interaction with the contract

    constructor() {
        _disableInitializers();
    }

    function initialize(IOstiumRegistry _registry) external initializer {
        if (address(_registry) == address(0)) {
            revert WrongParams();
        }

        registry = _registry;
        _setMaxSl_P(85);
    }

    // Modifiers
    modifier onlyGov() {
        isGov();
        _;
    }

    modifier onlyManager() {
        isManager();
        _;
    }

    modifier notDone() {
        isNotDone();
        _;
    }

    modifier onlyTrading() {
        isTrading();
        _;
    }

    function isGov() private view {
        if (msg.sender != registry.gov()) {
            revert NotGov(msg.sender);
        }
    }

    function isManager() private view {
        if (msg.sender != registry.manager()) {
            revert NotManager(msg.sender);
        }
    }

    function isPriceUpKeep(uint16 pairIndex) private view {
        string memory priceUpkeepType =
            IOstiumPairsStorage(registry.getContractAddress('pairsStorage')).oracle(pairIndex);
        if (msg.sender != registry.getContractAddress(bytes32(abi.encodePacked(priceUpkeepType, 'PriceUpkeep')))) {
            revert NotPriceUpKeep(msg.sender);
        }
    }

    function isDayTradeClosed(uint16 pairIndex, uint256 leverage, bool isDayTradingClosed) private view returns (bool) {
        if (isDayTradingClosed) {
            uint32 overnightMaxLeverage =
                IOstiumPairsStorage(registry.getContractAddress('pairsStorage')).pairOvernightMaxLeverage(pairIndex);
            if (overnightMaxLeverage != 0 && leverage > overnightMaxLeverage) {
                return true;
            }
        }
        return false;
    }

    function isNotDone() private view {
        if (isDone) {
            revert IsDone();
        }
    }

    function isTrading() private view {
        if (msg.sender != registry.getContractAddress('trading')) {
            revert NotTrading(msg.sender);
        }
    }

    function getContracts()
        private
        view
        returns (IOstiumTradingStorage storageT, IOstiumPairInfos pairInfos, IOstiumPairsStorage pairsStorage)
    {
        storageT = IOstiumTradingStorage(registry.getContractAddress('tradingStorage'));
        pairInfos = IOstiumPairInfos(registry.getContractAddress('pairInfos'));
        pairsStorage = IOstiumPairsStorage(registry.getContractAddress('pairsStorage'));
    }

    function _updateDynamicSpreadVolumes(
        uint16 pairIndex,
        bool isOpen,
        bool isBuy,
        uint256 collateral,
        uint32 leverage,
        IOstiumPairInfos pairInfos
    ) private {
        (uint256 decayedBuyVolume, uint256 decayedSellVolume) = TradingCallbacksLib.calculateDecayedVolumesWithPostFeeCollateral(
            pairIndex, isOpen, isBuy, collateral, leverage, pairInfos
        );
        pairInfos.updateDynamicSpreadState(pairIndex, decayedBuyVolume, decayedSellVolume);
    }

    function setMaxSl_P(uint256 _maxSl_P) external onlyGov {
        if (_maxSl_P == 0 || _maxSl_P > 100) {
            revert WrongParams();
        }
        _setMaxSl_P(_maxSl_P);
    }

    function _setMaxSl_P(uint256 _maxSl_P) private {
        maxSl_P = _maxSl_P.toUint8();
        emit MaxSlPUpdated(_maxSl_P);
    }

    function setVaultMaxAllowance() external onlyGov {
        IERC20 usdc = IERC20(IOstiumTradingStorage(registry.getContractAddress('tradingStorage')).usdc());
        SafeERC20.forceApprove(usdc, registry.getContractAddress('vault'), type(uint256).max);
    }

    function unsetVaultMaxAllowance(address _oldVault) external onlyGov {
        IERC20 usdc = IERC20(IOstiumTradingStorage(registry.getContractAddress('tradingStorage')).usdc());
        SafeERC20.forceApprove(usdc, _oldVault, 0);
    }

    function pause() external onlyManager {
        isPaused = !isPaused;

        emit Paused(isPaused);
    }

    function done() external onlyGov {
        isDone = !isDone;

        emit Done(isDone);
    }

    function openTradeMarketCallback(IOstiumPriceUpKeep.PriceUpKeepAnswer calldata a) external notDone {
        (IOstiumTradingStorage storageT, IOstiumPairInfos pairInfos, IOstiumPairsStorage pairsStorage) = getContracts();
        (uint256 _block, uint256 wantedPrice, uint256 slippageP, IOstiumTradingStorage.Trade memory trade,) =
            storageT.reqID_pendingMarketOrder(a.orderId);
        IOstiumTradingStorage.BuilderFee memory bf = storageT.getBuilderData(trade.trader, trade.pairIndex, a.orderId);

        isPriceUpKeep(trade.pairIndex);

        if (_block == 0) {
            return;
        }

        TradingCallbacksLib.PriceImpactResult memory result;
        CancelReason cancelReason;

        if (a.price <= 0 || a.bid <= 0 || a.ask <= 0) {
            cancelReason = CancelReason.MARKET_CLOSED;
        } else if (isDayTradeClosed(trade.pairIndex, trade.leverage, a.isDayTradingClosed)) {
            cancelReason = CancelReason.DAY_TRADE_NOT_ALLOWED;
        } else {
            (, uint32 takerFeeP,,,,) = pairInfos.pairOpeningFees(trade.pairIndex);
            uint256 calculatedPostFeeCollateral = TradingCallbacksLib.calculatePostFeeCollateral(
                trade.collateral, trade.leverage, trade.pairIndex, takerFeeP, pairsStorage, bf
            );

            result = TradingCallbacksLib.getDynamicTradePriceImpact(
                a.price, int192(a.ask), int192(a.bid), true, trade, pairInfos, calculatedPostFeeCollateral
            );

            trade.openPrice = result.priceAfterImpact.toUint192();

            cancelReason = TradingCallbacksLib.getOpenTradeMarketCancelReason(
                isPaused,
                wantedPrice,
                slippageP,
                uint192(a.price),
                trade,
                result.priceImpactP,
                IOstiumPairInfos(registry.getContractAddress('pairInfos')),
                pairsStorage,
                storageT
            );
        }

        if (cancelReason == CancelReason.NONE) {
            trade = registerTrade(a.orderId, trade, uint192(a.price), bf);

            if (result.isDynamic) {
                _updateDynamicSpreadVolumes(
                    trade.pairIndex, true, trade.buy, trade.collateral, trade.leverage, pairInfos
                );
            }
            uint256 tradeNotional = storageT.getOpenTradeInfo(trade.trader, trade.pairIndex, trade.index).oiNotional;
            IOstiumOpenPnl(registry.getContractAddress('openPnl')).updateAccTotalPnl(
                a.price, trade.openPrice, 0, tradeNotional, trade.pairIndex, trade.buy, true
            );
            IOstiumOpenPnl(registry.getContractAddress('openPnl')).updateAccClosedRollover(trade, 0);
            emit MarketOpenExecuted(a.orderId, trade, result.priceImpactP, tradeNotional);
        } else {
            uint256 oracleFee = pairsStorage.pairOracleFee(trade.pairIndex);
            if (trade.collateral > oracleFee) {
                storageT.transferUsdc(address(storageT), trade.trader, trade.collateral - oracleFee);
            } else {
                oracleFee = trade.collateral;
            }
            storageT.handleOracleFee(oracleFee);

            emit OracleFeeCharged(a.orderId, trade.trader, oracleFee);
            emit MarketOpenCanceled(a.orderId, trade.trader, trade.pairIndex, cancelReason);
        }
        storageT.unregisterPendingMarketOrder(a.orderId, true);
    }

    function closeTradeMarketCallback(IOstiumPriceUpKeep.PriceUpKeepAnswer calldata a) external notDone {
        (IOstiumTradingStorage storageT, IOstiumPairInfos pairInfos,) = getContracts();
        (
            uint256 _block,
            uint256 wantedPrice,
            uint256 slippageP,
            IOstiumTradingStorage.Trade memory trade,
            uint16 closePercentage
        ) = storageT.reqID_pendingMarketOrder(a.orderId);

        isPriceUpKeep(trade.pairIndex);

        if (_block == 0) {
            return;
        }

        IOstiumTradingStorage.Trade memory t = storageT.getOpenTrade(trade.trader, trade.pairIndex, trade.index);

        CancelReason cancelReason = t.leverage == 0
            ? CancelReason.NO_TRADE
            : ((a.price <= 0 || a.bid <= 0 || a.ask <= 0) ? CancelReason.MARKET_CLOSED : CancelReason.NONE);

        IOstiumTradingStorage.TradeInfo memory i = storageT.getOpenTradeInfo(t.trader, t.pairIndex, t.index);

        // Validate tradeId matches to prevent execution on replaced trades
        // Skip validation if storedTradeId == 0 (legacy order from before upgrade)
        if (cancelReason == CancelReason.NONE) {
            uint256 storedTradeId = storageT.pendingMarketCloseTradeIds(a.orderId);
            if (storedTradeId != 0 && i.tradeId != storedTradeId) {
                cancelReason = CancelReason.WRONG_TRADE;
            }
        }

        if (cancelReason != CancelReason.NO_TRADE) {
            if (cancelReason == CancelReason.NONE) {
                uint256 collateralToClose = t.collateral * closePercentage / 100e2;

                (
                    TradingCallbacksLib.TradeValueResult memory tvResult,
                    TradingCallbacksLib.PriceImpactResult memory piResult
                ) = TradingCallbacksLib.getTradeAndPriceData(
                    a,
                    t,
                    pairInfos,
                    i.initialLeverage,
                    IOstiumPairsStorage(registry.getContractAddress('pairsStorage')).pairMaxLeverage(t.pairIndex),
                    collateralToClose,
                    true
                );

                uint256 maxSlippage = (wantedPrice * slippageP) / 100 / 100;

                if (t.buy
                        ? piResult.priceAfterImpact < wantedPrice - maxSlippage
                        : piResult.priceAfterImpact > wantedPrice + maxSlippage) {
                    cancelReason = IOstiumTradingCallbacks.CancelReason.SLIPPAGE;
                } else {
                    if (piResult.isDynamic) {
                        _updateDynamicSpreadVolumes(t.pairIndex, false, t.buy, collateralToClose, t.leverage, pairInfos);
                    }

                    bool isLiquidated = tvResult.tradeValue < tvResult.liqMarginValue;

                    (tvResult.profitP,) = TradingCallbacksLib.currentPercentProfit(
                        t.openPrice.toInt256(),
                        piResult.priceAfterImpact.toInt256(),
                        t.buy,
                        int32(t.leverage),
                        int32(i.initialLeverage)
                    );
                    tvResult.tradeValue = pairInfos.getTradeValuePure(
                        collateralToClose, tvResult.profitP, tvResult.rolloverFees, tvResult.fundingFees
                    );

                    IOstiumOpenPnl(registry.getContractAddress('openPnl')).updateAccTotalPnl(
                            a.price,
                            t.openPrice,
                            piResult.priceAfterImpact,
                            i.oiNotional * closePercentage / 100e2,
                            t.pairIndex,
                            t.buy,
                            false
                        );
                    IOstiumOpenPnl(registry.getContractAddress('openPnl')).updateAccClosedRollover(t, closePercentage);

                    uint256 liquidationFee = isLiquidated ? tvResult.tradeValue : 0;

                    unregisterTrade(
                        a.orderId,
                        i.tradeId,
                        t,
                        isLiquidated ? 0 : tvResult.tradeValue,
                        liquidationFee,
                        collateralToClose
                    );

                    emit FeesChargedV2(a.orderId, i.tradeId, t.trader, tvResult.rolloverFees, tvResult.fundingFees);
                    emit MarketCloseExecutedV2(
                        a.orderId,
                        i.tradeId,
                        piResult.priceAfterImpact,
                        piResult.priceImpactP,
                        tvResult.profitP,
                        tvResult.tradeValue,
                        closePercentage
                    );

                    if (closePercentage == 100e2) {
                        // Full close and successfully closed - refund the oracle fee
                        IOstiumPairsStorage pairsStorage =
                            IOstiumPairsStorage(registry.getContractAddress('pairsStorage'));
                        uint256 oracleFee = pairsStorage.pairOracleFee(t.pairIndex);
                        storageT.refundOracleFee(oracleFee);
                        storageT.transferUsdc(address(storageT), t.trader, oracleFee);
                        emit OracleFeeRefunded(i.tradeId, t.trader, t.pairIndex, oracleFee);
                    }
                }
            }
        }

        if (cancelReason != CancelReason.NONE) {
            emit MarketCloseCanceled(a.orderId, i.tradeId, trade.trader, trade.pairIndex, trade.index, cancelReason);
        }

        storageT.clearDeprecatedBeingMarketClosed(trade.trader, trade.pairIndex, trade.index);
        if (cancelReason != CancelReason.WRONG_TRADE) {
            storageT.unregisterTrigger(
                trade.trader, trade.pairIndex, trade.index, IOstiumTradingStorage.LimitOrder.PENDING_CLOSE
            );
        }
        storageT.unregisterPendingMarketOrder(a.orderId, false);
    }

    function executeAutomationOpenOrderCallback(IOstiumPriceUpKeep.PriceUpKeepAnswer calldata a) external notDone {
        (IOstiumTradingStorage storageT, IOstiumPairInfos pairInfos, IOstiumPairsStorage pairsStorage) = getContracts();

        CancelReason cancelReason;
        (address trader, uint16 pairIndex, uint8 index,,) = storageT.reqID_pendingAutomationOrder(a.orderId);
        isPriceUpKeep(pairIndex);

        cancelReason = isPaused
            ? CancelReason.PAUSED
            : ((a.price <= 0 || a.bid <= 0 || a.ask <= 0)
                    ? CancelReason.MARKET_CLOSED
                    : !storageT.hasOpenLimitOrder(trader, pairIndex, index) ? CancelReason.NO_TRADE : CancelReason.NONE);

        IOstiumTradingStorage.OpenLimitOrder memory o;
        IOstiumTradingStorage.BuilderFee memory bf;
        if (cancelReason == CancelReason.NONE) {
            o = storageT.getOpenLimitOrder(trader, pairIndex, index);
            bf = storageT.getBuilderData(trader, pairIndex, index);

            // Validate limitOrderId matches to prevent execution on replaced limit orders
            // The stored ID is in the tradeId field of PendingAutomationOrder (repurposed for OPEN orders)
            (,,,, uint256 storedLimitOrderId) = storageT.reqID_pendingAutomationOrder(a.orderId);
            uint256 currentLimitOrderId = storageT.limitOrderIds(trader, pairIndex, index);
            // Skip validation if storedLimitOrderId == 0 (legacy order from before upgrade)
            // or if currentLimitOrderId == 0 (legacy limit order from before upgrade)
            if (storedLimitOrderId != 0 && currentLimitOrderId != 0 && currentLimitOrderId != storedLimitOrderId) {
                cancelReason = CancelReason.WRONG_TRADE;
            } else if (isDayTradeClosed(pairIndex, o.leverage, a.isDayTradingClosed)) {
                cancelReason = CancelReason.DAY_TRADE_NOT_ALLOWED;
            }
        }

        if (cancelReason == CancelReason.NONE) {
            IOstiumTradingStorage.Trade memory tempTrade =
                IOstiumTradingStorage.Trade(o.collateral, 0, o.tp, o.sl, o.trader, o.leverage, o.pairIndex, 0, o.buy);
            (, uint32 takerFeeP,,,,) = pairInfos.pairOpeningFees(pairIndex);
            uint256 calculatedPostFeeCollateral = TradingCallbacksLib.calculatePostFeeCollateral(
                o.collateral, o.leverage, pairIndex, takerFeeP, pairsStorage, bf
            );

            TradingCallbacksLib.PriceImpactResult memory result = TradingCallbacksLib.getDynamicTradePriceImpact(
                a.price, a.ask, a.bid, true, tempTrade, pairInfos, calculatedPostFeeCollateral
            );

            cancelReason = TradingCallbacksLib.getAutomationOpenOrderCancelReason(
                o, result.priceAfterImpact, uint192(a.price), result.priceImpactP, pairInfos, pairsStorage, storageT
            );

            if (cancelReason == CancelReason.NONE) {
                IOstiumTradingStorage.Trade memory trade = registerTrade(
                    a.orderId,
                    IOstiumTradingStorage.Trade(
                        o.collateral,
                        result.priceAfterImpact.toUint192(),
                        o.tp,
                        o.sl,
                        o.trader,
                        o.leverage,
                        o.pairIndex,
                        0,
                        o.buy
                    ),
                    uint192(a.price),
                    bf
                );

                if (result.isDynamic) {
                    _updateDynamicSpreadVolumes(
                        trade.pairIndex, true, trade.buy, trade.collateral, trade.leverage, pairInfos
                    );
                }
                uint256 tradeNotional = storageT.getOpenTradeInfo(trade.trader, trade.pairIndex, trade.index).oiNotional;

                IOstiumOpenPnl(registry.getContractAddress('openPnl')).updateAccTotalPnl(
                    a.price, trade.openPrice, 0, tradeNotional, trade.pairIndex, trade.buy, true
                );
                IOstiumOpenPnl(registry.getContractAddress('openPnl')).updateAccClosedRollover(trade, 0);
                storageT.unregisterOpenLimitOrder(o.trader, o.pairIndex, o.index);
                emit LimitOpenExecuted(a.orderId, o.index, trade, result.priceImpactP, tradeNotional);
            }
        }

        if (cancelReason != CancelReason.NONE) {
            emit AutomationOpenOrderCanceled(a.orderId, trader, pairIndex, cancelReason);
        }
        if (cancelReason != CancelReason.WRONG_TRADE) {
            storageT.unregisterTrigger(trader, pairIndex, index, IOstiumTradingStorage.LimitOrder.OPEN);
        }
        storageT.unregisterPendingAutomationOrder(a.orderId);
    }

    function executeAutomationCloseOrderCallback(IOstiumPriceUpKeep.PriceUpKeepAnswer calldata a) external notDone {
        (IOstiumTradingStorage storageT, IOstiumPairInfos pairInfos,) = getContracts();

        IOstiumTradingStorage.LimitOrder orderType;
        IOstiumTradingStorage.Trade memory t;

        (
            address trader,
            uint16 pairIndex,
            uint8 index,
            IOstiumTradingStorage.LimitOrder _orderType,
            uint256 storedTradeId
        ) = storageT.reqID_pendingAutomationOrder(a.orderId);
        isPriceUpKeep(pairIndex);
        t = storageT.getOpenTrade(trader, pairIndex, index);
        orderType = _orderType;

        CancelReason cancelReason = (a.price <= 0 || a.bid <= 0 || a.ask <= 0)
            ? CancelReason.MARKET_CLOSED
            : (t.leverage == 0 ? CancelReason.NO_TRADE : CancelReason.NONE);

        IOstiumTradingStorage.TradeInfo memory i = storageT.getOpenTradeInfo(t.trader, t.pairIndex, t.index);

        // Validate tradeId matches to prevent execution on replaced trades
        // Skip validation if storedTradeId == 0 (legacy order from before upgrade)
        if (cancelReason == CancelReason.NONE && storedTradeId != 0 && i.tradeId != storedTradeId) {
            cancelReason = CancelReason.WRONG_TRADE;
        }

        if (cancelReason == CancelReason.NONE) {
            bool isMarketPrice =
                orderType == IOstiumTradingStorage.LimitOrder.LIQ || orderType == IOstiumTradingStorage.LimitOrder.SL;

            (
                TradingCallbacksLib.TradeValueResult memory tvResult,
                TradingCallbacksLib.PriceImpactResult memory piResult
            ) = TradingCallbacksLib.getTradeAndPriceData(
                a,
                t,
                pairInfos,
                i.initialLeverage,
                IOstiumPairsStorage(registry.getContractAddress('pairsStorage')).pairMaxLeverage(t.pairIndex),
                t.collateral,
                isMarketPrice
            );

            bool isLiquidated = tvResult.tradeValue < tvResult.liqMarginValue;

            cancelReason = TradingCallbacksLib.getAutomationCloseOrderCancelReason(
                orderType,
                t,
                isMarketPrice ? uint192(a.price) : piResult.priceAfterImpact,
                isLiquidated ? 0 : tvResult.tradeValue,
                isDayTradeClosed(t.pairIndex, t.leverage, a.isDayTradingClosed)
            );

            if (cancelReason == CancelReason.NONE) {
                if (isMarketPrice) {
                    (tvResult.profitP,) = TradingCallbacksLib.currentPercentProfit(
                        t.openPrice.toInt256(),
                        piResult.priceAfterImpact.toInt256(),
                        t.buy,
                        int32(t.leverage),
                        int32(i.initialLeverage)
                    );
                    tvResult.tradeValue = pairInfos.getTradeValuePure(
                        t.collateral, tvResult.profitP, tvResult.rolloverFees, tvResult.fundingFees
                    );

                    isLiquidated = tvResult.tradeValue < tvResult.liqMarginValue;
                }

                if (piResult.isDynamic) {
                    _updateDynamicSpreadVolumes(t.pairIndex, false, t.buy, t.collateral, t.leverage, pairInfos);
                }

                IOstiumOpenPnl(registry.getContractAddress('openPnl')).updateAccTotalPnl(
                        a.price, t.openPrice, piResult.priceAfterImpact, i.oiNotional, t.pairIndex, t.buy, false
                    );
                IOstiumOpenPnl(registry.getContractAddress('openPnl')).updateAccClosedRollover(t, 100e2);

                uint256 liquidationFee = isLiquidated ? tvResult.tradeValue : 0;
                unregisterTrade(
                    a.orderId, i.tradeId, t, isLiquidated ? 0 : tvResult.tradeValue, liquidationFee, t.collateral
                );

                emit FeesChargedV2(a.orderId, i.tradeId, t.trader, tvResult.rolloverFees, tvResult.fundingFees);
                emit LimitCloseExecuted(
                    a.orderId,
                    i.tradeId,
                    isLiquidated ? IOstiumTradingStorage.LimitOrder.LIQ : orderType,
                    piResult.priceAfterImpact,
                    piResult.priceImpactP,
                    tvResult.profitP,
                    isLiquidated ? 0 : tvResult.tradeValue
                );
            }
        }

        if (cancelReason != CancelReason.NONE) {
            emit AutomationCloseOrderCanceled(a.orderId, i.tradeId, t.trader, t.pairIndex, orderType, cancelReason);
        }

        if (cancelReason != CancelReason.WRONG_TRADE) {
            storageT.unregisterTrigger(t.trader, t.pairIndex, t.index, orderType);
        }
        storageT.unregisterPendingAutomationOrder(a.orderId);
    }

    function registerTrade(
        uint256 tradeId,
        IOstiumTradingStorage.Trade memory trade,
        uint256 latestPrice,
        IOstiumTradingStorage.BuilderFee memory bf
    ) private returns (IOstiumTradingStorage.Trade memory) {
        (IOstiumTradingStorage storageT, IOstiumPairInfos pairInfos, IOstiumPairsStorage pairsStorage) = getContracts();

        uint256 reward;
        uint256 vaultReward;
        uint256 oracleFee;
        uint256 builderFee;

        (trade, reward, vaultReward, oracleFee, builderFee) = TradingCallbacksLib.executeRegisterTrade(
            tradeId,
            trade,
            latestPrice,
            bf,
            maxSl_P,
            storageT,
            pairInfos,
            pairsStorage,
            IOstiumVault(registry.getContractAddress('vault'))
        );

        emit DevFeeCharged(tradeId, trade.trader, reward);
        if (vaultReward > 0) {
            emit VaultOpeningFeeCharged(tradeId, trade.trader, vaultReward);
        }
        emit OracleFeeCharged(tradeId, trade.trader, oracleFee);
        if (builderFee > 0) {
            emit BuilderFeeCharged(tradeId, trade.trader, bf.builder, builderFee);
        }

        return trade;
    }

    function unregisterTrade(
        uint256 orderId,
        uint256 tradeId,
        IOstiumTradingStorage.Trade memory trade,
        uint256 usdcSentToTrader,
        uint256 liquidationFee, // PRECISION_6
        uint256 collateralToClose // PRECISION_6
    ) private {
        (IOstiumTradingStorage storageT,, IOstiumPairsStorage pairsStorage) = getContracts();

        TradingCallbacksLib.executeUnregisterTrade(
            trade,
            usdcSentToTrader,
            liquidationFee,
            collateralToClose,
            storageT,
            pairsStorage,
            IOstiumVault(registry.getContractAddress('vault'))
        );

        if (liquidationFee > 0) {
            emit VaultLiqFeeCharged(orderId, tradeId, trade.trader, liquidationFee);
        }
    }

    function handleRemoveCollateral(IOstiumPriceUpKeep.PriceUpKeepAnswer calldata a) external notDone {
        (IOstiumTradingStorage storageT, IOstiumPairInfos pairInfos, IOstiumPairsStorage pairsStorage) = getContracts();

        IOstiumTradingStorage.PendingRemoveCollateral memory request = storageT.getPendingRemoveCollateral(a.orderId);

        isPriceUpKeep(request.pairIndex);

        IOstiumTradingStorage.Trade memory trade =
            storageT.getOpenTrade(request.trader, request.pairIndex, request.index);

        IOstiumTradingStorage.TradeInfo memory tradeInfo =
            storageT.getOpenTradeInfo(request.trader, request.pairIndex, request.index);

        CancelReason cancelReason;

        if (isPaused) {
            cancelReason = CancelReason.PAUSED;
        } else if (trade.leverage == 0) {
            cancelReason = CancelReason.NO_TRADE;
        } else if (a.price <= 0 || a.bid <= 0 || a.ask <= 0) {
            cancelReason = CancelReason.MARKET_CLOSED;
        } else if (request.tradeId != 0 && tradeInfo.tradeId != request.tradeId) {
            // Validate tradeId matches to prevent execution on replaced trades
            // Skip validation if request.tradeId == 0 (legacy order from before upgrade)
            cancelReason = CancelReason.WRONG_TRADE;
        } else if (trade.collateral <= request.removeAmount) {
            // Check there's enough collateral to remove to prevents division by zero or underflow when collateral was reduced by other operations
            cancelReason = CancelReason.NOT_HIT;
        } else {
            // Calculate new leverage and position details
            uint256 tradeSize = trade.collateral.mulDiv(trade.leverage, 100, Math.Rounding.Ceil);
            trade.collateral -= request.removeAmount;
            trade.leverage = (tradeSize * PRECISION_6 / trade.collateral / 1e4).toUint32();

            if (isDayTradeClosed(trade.pairIndex, trade.leverage, a.isDayTradingClosed)) {
                cancelReason = CancelReason.DAY_TRADE_NOT_ALLOWED;
            } else {
                cancelReason = TradingCallbacksLib.getHandleRemoveCollateralCancelReason(
                    a, trade, pairInfos, pairsStorage, tradeInfo.initialLeverage
                );
            }
        }

        if (cancelReason == CancelReason.NONE) {
            trade.tp = TradingCallbacksLib.correctTp(
                trade.openPrice, trade.tp, trade.leverage, tradeInfo.initialLeverage, trade.buy
            );
            trade.sl = TradingCallbacksLib.correctToNullSl(
                trade.openPrice, trade.sl, trade.leverage, tradeInfo.initialLeverage, trade.buy, maxSl_P
            );

            storageT.transferUsdc(address(storageT), request.trader, request.removeAmount);
            storageT.updateTrade(trade);
            pairsStorage.updateGroupCollateral(trade.pairIndex, request.removeAmount, trade.buy, false);

            emit RemoveCollateralExecuted(
                a.orderId,
                tradeInfo.tradeId,
                request.trader,
                request.pairIndex,
                request.removeAmount,
                trade.leverage,
                trade.tp,
                trade.sl
            );
        } else {
            emit RemoveCollateralRejected(
                a.orderId, tradeInfo.tradeId, request.trader, request.pairIndex, request.removeAmount, cancelReason
            );
        }

        storageT.unregisterPendingRemoveCollateral(a.orderId);
        if (cancelReason != CancelReason.WRONG_TRADE) {
            storageT.unregisterTrigger(
                request.trader, request.pairIndex, request.index, IOstiumTradingStorage.LimitOrder.REMOVE_COLLATERAL
            );
        }
    }
}

src/OstiumTradingStorage.sol.content:
// SPDX-License-Identifier: MIT
import '@openzeppelin/contracts/utils/math/SafeCast.sol';
import '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import '@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol';
import '@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol';

import './lib/ChainUtils.sol';
import './interfaces/IOstiumTradingStorage.sol';
import './interfaces/IOstiumRegistry.sol';
import './interfaces/IOstiumPairInfos.sol';

pragma solidity ^0.8.24;

contract OstiumTradingStorage is IOstiumTradingStorage, Initializable {
    using SafeCast for uint256;
    using SafeERC20 for IERC20;

    uint64 constant PRECISION_18 = 1e18; // 18 decimals
    uint32 constant PRECISION_6 = 1e6; // 6 decimals
    uint8 constant PRECISION_2 = 1e2; // 2 decimals

    address public usdc;

    IOstiumRegistry public registry;

    uint256 public devFees; // PRECISION_6 (USDC)
    uint32 public totalOpenTradesCount;
    uint8 public maxTradesPerPair;
    uint8 public maxPendingMarketOrders;

    // Trades mappings
    mapping(
        address trader => mapping(uint16 pairIndex => mapping(uint8 tradeIndex => IOstiumTradingStorage.Trade))
    ) public openTrades;
    mapping(address trader => mapping(uint16 pairIndex => mapping(uint8 tradeIndex => TradeInfo))) public
        openTradesInfo;
    mapping(address trader => mapping(uint16 pairIndex => uint32)) public openTradesCount;

    // Limit orders mappings
    mapping(address trader => mapping(uint16 pairIndex => mapping(uint8 orderIndex => uint256))) public
        openLimitOrderIds;
    mapping(address trader => mapping(uint16 pairIndex => uint8)) public openLimitOrdersCount;
    mapping(
        address trader
            => mapping(
            uint16 pairIndex => mapping(uint8 index => mapping(IOstiumTradingStorage.LimitOrder orderType => uint256))
        )
    ) public orderTriggerBlock;
    mapping(uint16 pairIndex => OpenLimitOrder[]) public pairLimitOrders;

    // Pending orders mappings
    mapping(uint256 orderId => PendingMarketOrderV2) public reqID_pendingMarketOrder;
    mapping(uint256 orderId => PendingAutomationOrder) public reqID_pendingAutomationOrder;

    mapping(address trader => uint256[]) public pendingOrderIds;
    mapping(address trader => mapping(uint16 pairIndex => uint8)) public pendingMarketOpenCount;
    mapping(address trader => mapping(uint16 pairIndex => uint8)) public pendingMarketCloseCount;

    // List of open trades & limit orders
    mapping(uint16 pairIndex => address[]) public pairTraders;
    mapping(address trader => mapping(uint16 pairIndex => uint256)) public pairTradersId;

    // Current and max open interests for each pair
    mapping(uint16 pairIndex => uint256[3]) public openInterest; // [ notional long (18 dec), notional short (18 dec), $ max (6 dec)]

    mapping(uint256 => PendingRemoveCollateral) public reqID_pendingRemoveCollateral;

    mapping(
        address trader => mapping(uint16 pairIndex => mapping(uint256 tradeIndex => IOstiumTradingStorage.BuilderFee))
    ) public builderData;

    uint256 public limitOrderIdCounter; // Counter for unique limit order IDs

    mapping(address trader => mapping(uint16 pairIndex => mapping(uint8 index => uint256))) public limitOrderIds;

    mapping(uint256 orderId => uint256 tradeId) public pendingMarketCloseTradeIds;

    constructor() {
        _disableInitializers();
    }

    function initialize(IOstiumRegistry _registry, address _usdc) external initializer {
        if (address(_registry) == address(0) || address(_usdc) == address(0)) revert NullAddr();

        usdc = _usdc;
        registry = _registry;
        _setMaxTradesPerPair(10);
        _setMaxPendingMarketOrders(50);
    }

    modifier onlyGov() {
        _onlyGov();
        _;
    }

    function _onlyGov() internal view {
        if (msg.sender != registry.gov()) revert NotGov(msg.sender);
    }

    modifier onlyTrading() {
        _onlyTrading();
        _;
    }

    function _onlyTrading() internal view {
        if (msg.sender != registry.getContractAddress('trading')) revert NotTrading(msg.sender);
    }

    modifier onlyCallbacks() {
        _onlyCallbacks();
        _;
    }

    function _onlyCallbacks() internal view {
        if (msg.sender != registry.getContractAddress('callbacks')) revert NotCallbacks(msg.sender);
    }

    modifier onlyTradingOrCallbacks() {
        _onlyTradingOrCallbacks();
        _;
    }

    modifier onlyManager() {
        _onlyManager();
        _;
    }

    function _onlyManager() internal view {
        if (msg.sender != registry.manager()) revert NotManager(msg.sender);
    }

    function _onlyTradingOrCallbacks() internal view {
        if (
            msg.sender != registry.getContractAddress('trading')
                && msg.sender != registry.getContractAddress('callbacks')
        ) revert NotTradingOrCallbacks(msg.sender);
    }

    function setMaxTradesPerPair(uint256 _maxTradesPerPair) external onlyGov {
        _setMaxTradesPerPair(_maxTradesPerPair);
    }

    function _setMaxTradesPerPair(uint256 _maxTradesPerPair) private {
        if (_maxTradesPerPair == 0 || _maxTradesPerPair > type(uint8).max) revert WrongParams();
        maxTradesPerPair = _maxTradesPerPair.toUint8();
        emit MaxTradesPerPairUpdated(_maxTradesPerPair);
    }

    function setMaxPendingMarketOrders(uint256 _maxPendingMarketOrders) external onlyGov {
        _setMaxPendingMarketOrders(_maxPendingMarketOrders);
    }

    function _setMaxPendingMarketOrders(uint256 _maxPendingMarketOrders) private {
        if (_maxPendingMarketOrders == 0 || _maxPendingMarketOrders > type(uint8).max) revert WrongParams();
        maxPendingMarketOrders = _maxPendingMarketOrders.toUint8();
        emit MaxPendingMarketOrdersUpdated(_maxPendingMarketOrders);
    }

    function setMaxOpenInterest(uint16 _pairIndex, uint256 _newMaxOpenInterest) public onlyManager {
        openInterest[_pairIndex][2] = _newMaxOpenInterest;
        emit MaxOpenInterestUpdated(_pairIndex, _newMaxOpenInterest);
    }

    function setMaxOpenInterestArray(uint16[] calldata _indices, uint256[] calldata _newMaxOpenInterests)
        external
        onlyManager
    {
        if (_indices.length != _newMaxOpenInterests.length) {
            revert WrongParams();
        }
        for (uint256 i = 0; i < _indices.length; i++) {
            setMaxOpenInterest(_indices[i], _newMaxOpenInterests[i]);
        }
    }

    function storeTrade(Trade memory _trade, TradeInfo memory _tradeInfo) external onlyCallbacks {
        _trade.index = firstEmptyTradeIndex(_trade.trader, _trade.pairIndex);
        openTrades[_trade.trader][_trade.pairIndex][_trade.index] = _trade;

        ++openTradesCount[_trade.trader][_trade.pairIndex];
        ++totalOpenTradesCount;

        if (openTradesCount[_trade.trader][_trade.pairIndex] == 1) {
            pairTradersId[_trade.trader][_trade.pairIndex] = pairTraders[_trade.pairIndex].length;
            pairTraders[_trade.pairIndex].push(_trade.trader);
        }

        openTradesInfo[_trade.trader][_trade.pairIndex][_trade.index] = _tradeInfo;

        updateOpenInterest(_trade.pairIndex, _tradeInfo.oiNotional, true, _trade.buy);
    }

    function unregisterTrade(address _trader, uint16 _pairIndex, uint8 _index, uint256 _collateralToClose)
        external
        onlyCallbacks
    {
        Trade storage t = openTrades[_trader][_pairIndex][_index];
        TradeInfo storage i = openTradesInfo[_trader][_pairIndex][_index];
        if (t.leverage == 0) return;

        uint256 oiNotionalToClose = i.oiNotional * _collateralToClose / t.collateral;
        updateOpenInterest(_pairIndex, oiNotionalToClose, false, t.buy);

        if (_collateralToClose != t.collateral) {
            t.collateral = t.collateral - _collateralToClose;
            i.oiNotional = i.oiNotional - oiNotionalToClose;
            return;
        }

        if (openTradesCount[_trader][_pairIndex] == 1) {
            uint256 _pairTradersId = pairTradersId[_trader][_pairIndex];
            address[] storage p = pairTraders[_pairIndex];

            p[_pairTradersId] = p[p.length - 1];
            pairTradersId[p[_pairTradersId]][_pairIndex] = _pairTradersId;

            delete pairTradersId[_trader][_pairIndex];
            p.pop();
        }

        delete openTrades[_trader][_pairIndex][_index];
        delete openTradesInfo[_trader][_pairIndex][_index];
        _removeAllTriggers(_trader, _pairIndex, _index);

        --openTradesCount[_trader][_pairIndex];
        --totalOpenTradesCount;
    }

    function storePendingMarketOrder(
        PendingMarketOrderV2 calldata _order,
        uint256 _id,
        bool _open,
        BuilderFee calldata bf
    ) external onlyTrading {
        pendingOrderIds[_order.trade.trader].push(_id);

        reqID_pendingMarketOrder[_id] = _order;
        reqID_pendingMarketOrder[_id].block = ChainUtils.getBlockNumber();

        if (_open) {
            pendingMarketOpenCount[_order.trade.trader][_order.trade.pairIndex]++;
            builderData[_order.trade.trader][_order.trade.pairIndex][_id] = bf;
        } else {
            pendingMarketCloseCount[_order.trade.trader][_order.trade.pairIndex]++;
        }
    }

    function storePendingMarketCloseTradeId(uint256 orderId, uint256 tradeId) external onlyTrading {
        pendingMarketCloseTradeIds[orderId] = tradeId;
    }

    function unregisterPendingMarketOrder(uint256 _id, bool _open) external onlyTradingOrCallbacks {
        PendingMarketOrderV2 memory _order = reqID_pendingMarketOrder[_id];
        uint256[] storage orderIds = pendingOrderIds[_order.trade.trader];

        for (uint256 i = 0; i < orderIds.length; i++) {
            if (orderIds[i] == _id) {
                if (_open) {
                    pendingMarketOpenCount[_order.trade.trader][_order.trade.pairIndex]--;
                    delete builderData[_order.trade.trader][_order.trade.pairIndex][_id];
                } else {
                    pendingMarketCloseCount[_order.trade.trader][_order.trade.pairIndex]--;
                    delete pendingMarketCloseTradeIds[_id];
                }

                orderIds[i] = orderIds[orderIds.length - 1];
                orderIds.pop();

                delete reqID_pendingMarketOrder[_id];
                return;
            }
        }
    }

    function updateOpenInterest(uint16 _pairIndex, uint256 _oiNotional, bool _open, bool _long) private {
        uint256 index = _long ? 0 : 1;
        uint256[3] storage o = openInterest[_pairIndex];
        o[index] = _open ? o[index] + _oiNotional : o[index] - _oiNotional;
    }

    function storeOpenLimitOrder(OpenLimitOrder calldata o, BuilderFee calldata bf) external onlyTrading {
        pairLimitOrders[o.pairIndex].push(o);
        openLimitOrderIds[o.trader][o.pairIndex][o.index] = pairLimitOrders[o.pairIndex].length - 1;
        openLimitOrdersCount[o.trader][o.pairIndex]++;
        builderData[o.trader][o.pairIndex][o.index] = bf;
        limitOrderIds[o.trader][o.pairIndex][o.index] = ++limitOrderIdCounter;
    }

    function updateOpenLimitOrder(OpenLimitOrder calldata _o) external onlyTrading {
        if (!hasOpenLimitOrder(_o.trader, _o.pairIndex, _o.index)) return;
        OpenLimitOrder storage o = pairLimitOrders[_o.pairIndex][openLimitOrderIds[_o.trader][_o.pairIndex][_o.index]];
        o.collateral = _o.collateral;
        o.buy = _o.buy;
        o.leverage = _o.leverage;
        o.tp = _o.tp;
        o.sl = _o.sl;
        o.targetPrice = _o.targetPrice;
        o.orderType = _o.orderType;
        o.lastUpdated = uint32(block.timestamp);
    }

    function unregisterOpenLimitOrder(address _trader, uint16 _pairIndex, uint8 _index)
        external
        onlyTradingOrCallbacks
    {
        if (!hasOpenLimitOrder(_trader, _pairIndex, _index)) return;

        uint256 id = openLimitOrderIds[_trader][_pairIndex][_index];
        pairLimitOrders[_pairIndex][id] = pairLimitOrders[_pairIndex][pairLimitOrders[_pairIndex].length - 1];
        openLimitOrderIds[
            pairLimitOrders[_pairIndex][id].trader
        ][pairLimitOrders[_pairIndex][id].pairIndex][pairLimitOrders[_pairIndex][id].index] = id;

        delete openLimitOrderIds[_trader][_pairIndex][_index];
        delete builderData[_trader][_pairIndex][_index];
        delete limitOrderIds[_trader][_pairIndex][_index];
        pairLimitOrders[_pairIndex].pop();

        openLimitOrdersCount[_trader][_pairIndex]--;
    }

    function setTrigger(address _trader, uint16 _pairIndex, uint8 _index, IOstiumTradingStorage.LimitOrder _orderType)
        external
        onlyTrading
    {
        orderTriggerBlock[_trader][_pairIndex][_index][_orderType] = ChainUtils.getBlockNumber();
    }

    function unregisterTrigger(
        address _trader,
        uint16 _pairIndex,
        uint8 _index,
        IOstiumTradingStorage.LimitOrder _orderType
    ) external onlyTradingOrCallbacks {
        delete orderTriggerBlock[_trader][_pairIndex][_index][_orderType];
    }

    function clearDeprecatedBeingMarketClosed(address _trader, uint16 _pairIndex, uint8 _index)
        external
        onlyTradingOrCallbacks
    {
        if (openTradesInfo[_trader][_pairIndex][_index].deprecatedBeingMarketClosed) {
            openTradesInfo[_trader][_pairIndex][_index].deprecatedBeingMarketClosed = false;
        }
    }

    /// @dev Clears all trigger types for a trade index
    function _removeAllTriggers(address _trader, uint16 _pairIndex, uint8 _index) private {
        for (uint8 i = 0; i <= uint8(type(IOstiumTradingStorage.LimitOrder).max); i++) {
            IOstiumTradingStorage.LimitOrder triggerType = IOstiumTradingStorage.LimitOrder(i);
            // Skip OPEN Limit Order triggers
            if (triggerType == IOstiumTradingStorage.LimitOrder.OPEN) continue;
            delete orderTriggerBlock[_trader][_pairIndex][_index][triggerType];
        }
    }

    function storePendingAutomationOrder(PendingAutomationOrder calldata _automationOrder, uint256 _orderId)
        external
        onlyTrading
    {
        reqID_pendingAutomationOrder[_orderId] = _automationOrder;
    }

    function unregisterPendingAutomationOrder(uint256 _orderId) external onlyCallbacks {
        delete reqID_pendingAutomationOrder[_orderId];
    }

    function updateSl(address _trader, uint16 _pairIndex, uint8 _index, uint256 _newSl) external onlyTrading {
        _updateSl(_trader, _pairIndex, _index, _newSl);
    }

    function _updateSl(address _trader, uint16 _pairIndex, uint8 _index, uint256 _newSl) internal {
        if (_newSl > type(uint192).max) {
            revert WrongParams();
        }
        Trade storage t = openTrades[_trader][_pairIndex][_index];
        TradeInfo storage i = openTradesInfo[_trader][_pairIndex][_index];
        if (t.leverage == 0) return;
        t.sl = _newSl.toUint192();
        i.slLastUpdated = block.timestamp.toUint32();
    }

    function updateTp(address _trader, uint16 _pairIndex, uint8 _index, uint256 _newTp) external onlyTrading {
        _updateTp(_trader, _pairIndex, _index, _newTp);
    }

    function _updateTp(address _trader, uint16 _pairIndex, uint8 _index, uint256 _newTp) internal {
        if (_newTp > type(uint192).max) {
            revert WrongParams();
        }
        Trade storage t = openTrades[_trader][_pairIndex][_index];
        TradeInfo storage i = openTradesInfo[_trader][_pairIndex][_index];
        if (t.leverage == 0) return;
        t.tp = _newTp.toUint192();
        i.tpLastUpdated = block.timestamp.toUint32();
    }

    function updateTrade(Trade calldata _t) external onlyTradingOrCallbacks {
        IOstiumTradingStorage.Trade storage t = openTrades[_t.trader][_t.pairIndex][_t.index];
        IOstiumTradingStorage.TradeInfo storage i = openTradesInfo[_t.trader][_t.pairIndex][_t.index];

        if (t.leverage == 0) {
            return;
        }
        t.collateral = _t.collateral;
        t.leverage = _t.leverage;

        if (_t.tp != t.tp) {
            _updateTp(_t.trader, _t.pairIndex, _t.index, _t.tp);
        }
        if (_t.sl != t.sl) {
            _updateSl(_t.trader, _t.pairIndex, _t.index, _t.sl);
        }
        if (_t.leverage > i.initialLeverage) {
            i.initialLeverage = _t.leverage;
        }
    }

    function handleOpeningFees(
        uint16 _pairIndex,
        uint256 latestPrice,
        uint256 _leveragedPositionSize,
        uint32 leverage,
        bool isBuy
    ) external onlyCallbacks returns (uint256 devFee, uint256 vaultFee) {
        uint256 oiLong = openInterest[_pairIndex][0] * latestPrice / PRECISION_18 / 1e12;
        uint256 oiShort = openInterest[_pairIndex][1] * latestPrice / PRECISION_18 / 1e12;

        int256 oiDelta = oiLong.toInt256() - oiShort.toInt256();

        (devFee, vaultFee) = IOstiumPairInfos(registry.getContractAddress('pairInfos'))
            .getOpeningFee(
                _pairIndex,
                isBuy ? _leveragedPositionSize.toInt256() : -_leveragedPositionSize.toInt256(),
                leverage,
                oiDelta
            );

        devFees += devFee;
    }

    function handleOracleFee(uint256 _amount) external onlyTradingOrCallbacks {
        devFees += _amount;
    }

    function refundOracleFee(uint256 _amount) external onlyTradingOrCallbacks {
        if (_amount > devFees) {
            revert RefundOracleFeeFailed();
        }
        devFees -= _amount;
    }

    function claimFees(uint256 _amount) external onlyGov {
        uint256 _devFees = devFees;
        if (_amount > _devFees || _amount == 0) {
            revert WrongParams();
        }
        devFees -= _amount;

        SafeERC20.safeTransfer(IERC20(usdc), registry.dev(), _amount);
    }

    function transferUsdc(address _from, address _to, uint256 _amount) external onlyTradingOrCallbacks {
        if (_from == address(this)) {
            SafeERC20.safeTransfer(IERC20(usdc), _to, _amount);
        } else {
            SafeERC20.safeTransferFrom(IERC20(usdc), _from, _to, _amount);
        }
    }

    function firstEmptyTradeIndex(address _trader, uint16 _pairIndex) public view returns (uint8) {
        for (uint8 i = 0; i < maxTradesPerPair; i++) {
            if (openTrades[_trader][_pairIndex][i].leverage == 0) {
                return i;
            }
        }
        revert NotEmptyIndex();
    }

    function firstEmptyOpenLimitIndex(address _trader, uint16 _pairIndex) external view returns (uint8) {
        for (uint8 i = 0; i < maxTradesPerPair; i++) {
            if (!hasOpenLimitOrder(_trader, _pairIndex, i)) {
                return i;
            }
        }
        revert NotEmptyIndex();
    }

    function hasOpenLimitOrder(address _trader, uint16 _pairIndex, uint8 _index) public view returns (bool) {
        if (pairLimitOrders[_pairIndex].length == 0) return false;
        OpenLimitOrder storage o = pairLimitOrders[_pairIndex][openLimitOrderIds[_trader][_pairIndex][_index]];
        return o.trader == _trader && o.pairIndex == _pairIndex && o.index == _index;
    }

    function pairTradersArray(uint16 _pairIndex) external view returns (address[] memory) {
        return pairTraders[_pairIndex];
    }

    function pairTradersCount(uint16 _pairIndex) external view returns (uint256) {
        return pairTraders[_pairIndex].length;
    }

    function getPendingOrderIds(address _trader) external view returns (uint256[] memory) {
        return pendingOrderIds[_trader];
    }

    function pendingOrderIdsCount(address _trader) external view returns (uint256) {
        return pendingOrderIds[_trader].length;
    }

    function getOpenLimitOrder(address _trader, uint16 _pairIndex, uint8 _index)
        external
        view
        returns (OpenLimitOrder memory)
    {
        if (!hasOpenLimitOrder(_trader, _pairIndex, _index)) {
            revert NoOpenLimitOrder(_trader, _pairIndex, _index);
        }
        return pairLimitOrders[_pairIndex][openLimitOrderIds[_trader][_pairIndex][_index]];
    }

    function getOpenLimitOrderByIndex(uint16 _pairIndex, uint256 _index) external view returns (OpenLimitOrder memory) {
        if (_index >= pairLimitOrders[_pairIndex].length) {
            revert WrongParams();
        }
        return pairLimitOrders[_pairIndex][_index];
    }

    function getOpenLimitOrders(uint16 _pairIndex) external view returns (OpenLimitOrder[] memory) {
        return pairLimitOrders[_pairIndex];
    }

    function getOpenTrade(address _trader, uint16 _pairIndex, uint8 _index) external view returns (Trade memory) {
        return openTrades[_trader][_pairIndex][_index];
    }

    function getOpenTradeInfo(address _trader, uint16 _pairIndex, uint8 _index)
        external
        view
        returns (TradeInfo memory)
    {
        return openTradesInfo[_trader][_pairIndex][_index];
    }

    function getPairOpeningInterestInfo(uint16 _pairIndex) external view returns (uint256, uint256, uint256) {
        return (openInterest[_pairIndex][0], openInterest[_pairIndex][1], openInterest[_pairIndex][2]);
    }

    function totalOpenLimitOrders(uint16 pairIndex) external view returns (uint256) {
        return pairLimitOrders[pairIndex].length;
    }

    function storePendingRemoveCollateral(PendingRemoveCollateral calldata request, uint256 orderId)
        external
        onlyTrading
    {
        reqID_pendingRemoveCollateral[orderId] = request;
    }

    function getPendingRemoveCollateral(uint256 orderId) external view returns (PendingRemoveCollateral memory) {
        return reqID_pendingRemoveCollateral[orderId];
    }

    function unregisterPendingRemoveCollateral(uint256 orderId) external onlyCallbacks {
        delete reqID_pendingRemoveCollateral[orderId];
    }

    function getBuilderData(address _trader, uint16 _pairIndex, uint256 _index)
        external
        view
        returns (BuilderFee memory)
    {
        return builderData[_trader][_pairIndex][_index];
    }
}

